package com.abitusd.app.feature.clock.domain

/**
 * Beep schedules of field tests (11f), generated by the app (no third party audio).
 * - 20 m shuttle run (Léger 1988): 8.5 km/h at level 1, +0.5 km/h per level, shuttles per level
 *   from the published level table (topendsports.com, beeptest.net).
 * - Yo-Yo Intermittent Recovery Level 1: 2 x 20 m bouts at each speed with 10 s active recovery
 *   (topendsports.com level table, after Bangsbo et al. 2008).
 * - 30 m sprint: 3, 2, 1 countdown and a start beep; the athlete stops the watch at the finish.
 */
enum class FieldTest { SHUTTLE_RUN, YO_YO_IR1, SPRINT_30 }

/** One beep: when it sounds (ms from start), the level and shuttle it closes. */
data class TestBeep(
    val atMs: Long,
    val level: Int,
    val shuttle: Int,
    val start: Boolean = false,
)

object FieldTests {
    private const val LEG_M = 20.0
    private const val KMH_TO_MS = 3.6
    private const val MS = 1000.0
    private const val RECOVERY_MS = 10_000L
    private const val COUNTDOWN_MS = 3_000L

    private val SHUTTLES = listOf(7, 8, 8, 9, 9, 10, 10, 11, 11, 11, 12, 12, 13, 13, 13, 14, 14, 15, 15, 16, 16)
    private const val SHUTTLE_START_KMH = 8.5
    private const val SHUTTLE_STEP_KMH = 0.5

    /** Yo-Yo IR1 speed level to (km/h, bouts). */
    private val YO_YO =
        listOf(
            5 to (10.0 to 1),
            8 to (11.5 to 1),
            11 to (13.0 to 2),
            12 to (13.5 to 3),
            13 to (14.0 to 4),
        ) + (14..23).map { it to (14.5 + (it - 14) * SHUTTLE_STEP_KMH to 8) }

    private fun legMs(kmh: Double) = (LEG_M / (kmh / KMH_TO_MS) * MS).toLong()

    fun schedule(test: FieldTest): List<TestBeep> =
        when (test) {
            FieldTest.SHUTTLE_RUN -> shuttleRun()
            FieldTest.YO_YO_IR1 -> yoYo()
            FieldTest.SPRINT_30 -> listOf(TestBeep(COUNTDOWN_MS, 0, 0, start = true))
        }

    private fun shuttleRun(): List<TestBeep> {
        var at = COUNTDOWN_MS
        val beeps = mutableListOf(TestBeep(at, 1, 0, start = true))
        SHUTTLES.forEachIndexed { i, count ->
            val leg = legMs(SHUTTLE_START_KMH + i * SHUTTLE_STEP_KMH)
            repeat(count) { s ->
                at += leg
                beeps += TestBeep(at, i + 1, s + 1)
            }
        }
        return beeps
    }

    private fun yoYo(): List<TestBeep> {
        var at = COUNTDOWN_MS
        val beeps = mutableListOf(TestBeep(at, YO_YO.first().first, 0, start = true))
        YO_YO.forEach { (level, speed) ->
            val leg = legMs(speed.first)
            repeat(speed.second) { b ->
                at += leg
                beeps += TestBeep(at, level, b + 1)
                at += leg
                beeps += TestBeep(at, level, b + 1)
                at += RECOVERY_MS
                beeps += TestBeep(at, level, b + 1, start = true)
            }
        }
        return beeps
    }
}
